CREATE DATABASE IF NOT EXISTS stocksense_php CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE stocksense_php;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS stocks(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,quantity INT NOT NULL DEFAULT 0,unit VARCHAR(40) NOT NULL,expiry DATE NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(name,unit,expiry));
CREATE TABLE IF NOT EXISTS billings(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,quantity INT NOT NULL,unit VARCHAR(40) NOT NULL,price DECIMAL(12,2) NOT NULL DEFAULT 0,date TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS clothing_items(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,quantity_value INT NOT NULL DEFAULT 0,quantity_unit ENUM('Pieces','Sets') NOT NULL DEFAULT 'Pieces',restock_date DATE NOT NULL DEFAULT (CURRENT_DATE),assigned_to VARCHAR(190) NOT NULL,status ENUM('available','expired','discount') NOT NULL DEFAULT 'available',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS clothing_billings(id INT AUTO_INCREMENT PRIMARY KEY,item_id INT NULL,item_name VARCHAR(190) NOT NULL,quantity_billed INT NOT NULL,unit VARCHAR(40) NOT NULL,billed_by VARCHAR(190) NULL,date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(item_id) REFERENCES clothing_items(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS notifications(id INT AUTO_INCREMENT PRIMARY KEY,type VARCHAR(30) DEFAULT 'weather',message TEXT NOT NULL,related_item VARCHAR(255) NULL,date TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS news_articles(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(500) NOT NULL UNIQUE,description TEXT,url TEXT,image TEXT,published_at DATETIME NULL,source VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS missing_products(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL UNIQUE,checked_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS support_messages(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,email VARCHAR(190) NOT NULL,message TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
